from collections import deque

def resolve(path, cwd, links):
    def parent(cur):
        if cur == '/':
            return '/'
        idx = cur.rfind('/')
        if idx <= 0:
            return '/'
        return cur[:idx]

    def join(cur, name):
        if cur == '/':
            return '/' + name
        return cur + '/' + name

    if path.startswith('/'):
        current = '/'
    else:
        current = cwd

    components = deque(path.split('/'))
    link_count = 0

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            current = parent(current)
        else:
            candidate = join(current, comp)
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                target_parts = deque(target.split('/'))
                if target.startswith('/'):
                    current = '/'
                    # prepend target_parts to components
                    new_components = deque()
                    new_components.extend(target_parts)
                    new_components.extend(components)
                    components = new_components
                else:
                    new_components = deque()
                    new_components.extend(target_parts)
                    new_components.extend(components)
                    components = new_components
                    # current stays as is (directory containing the link)
            else:
                current = candidate

    return current

